def partition(nums, low, high):
    pivot = nums[(low + high) // 2]
    while low <= high:
        while nums[low] < pivot:
            low += 1
        while nums[high] > pivot:
            high -= 1
        if low <= high:
            nums[low], nums[high] = nums[high], nums[low]
            low, high = low + 1, high - 1
    return low 

def select(nums, k):
    low, high = 0, len(nums) - 1
    while high > low:
        pivot = partition(nums, low, high)
        if pivot < k:
            low = pivot
        elif pivot > k:
            high = pivot - 1
        else:
            return nums[k]
    return nums[low]

