        class Solution {
            public List<Integer> uniqueDigitsAndDivisibleByThree(List<Integer> x) {
                List<Integer> answer = new ArrayList<>();

                for (Integer num : x) {
                    if (num % 3 == 0 && !hasEvenDigit(num)) {
                        answer.add(num);
                    }
                }

                Collections.sort(answer);

                return answer;
            }

            private boolean hasEvenDigit(Integer num) {
